package org.yuzu.yuzu_emu.features.settings.model

enum class ImpactLevel {
    NONE,
    LOW,
    MED,
    HIGH,
    None,
    Low,
    Med,
    High
}

data class SettingImpact(
    val performance: ImpactLevel = ImpactLevel.NONE,
    val heat: ImpactLevel = ImpactLevel.NONE,
    val compatibility: ImpactLevel = ImpactLevel.NONE,
    val quality: ImpactLevel = ImpactLevel.NONE,
    val effectEn: String = "",
    val effectRu: String = ""
) {
    fun formatBadge(isRu: Boolean): String = ""

    fun formatTooltip(isRu: Boolean): String = if (isRu) effectRu.ifEmpty { effectEn } else effectEn
}

